/**
 * Valida una dirección de correo electrónico.
 * Utiliza filter_var para la validación base RFC y aplica reglas extra.
 *
 * @param string $email Dirección de correo a validar
 * @return bool True si es válida, False en caso contrario
 */
function validarEmail(string $email): bool {
    // 1. Validar longitud máxima (RFC 5321 limita el total a 254 caracteres)
    // Se usa strlen() ya que los límites de email se miden tradicionalmente en bytes.
    if (strlen($email) > 255) {
        return false;
    }

    // 2. Validación estándar con filter_var (cumple con RFC 822/5322)
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return false;
    }

    // 3. Extra: El dominio no debe ser puramente numérico
    // filter_var garantiza que existe exactamente un '@', por lo que explode es seguro aquí.
    [, $domain] = explode('@', $email);
    $domainLower = strtolower($domain);

    // Un dominio válido debe contener al menos un carácter alfabético.
    // Esto descarta direcciones como user@192.168.0.1 o user@123
    if (!preg_match('/[a-zA-Z]/', $domainLower)) {
        return false;
    }

    return true;
}
```

